import hashlib

def enabled(flag: str, user_id: str, percent: int) -> bool:
    # băm ổn định: cùng flag + user luôn ra cùng bucket 0..99
    h = hashlib.sha256(f"{flag}:{user_id}".encode()).digest()
    return int.from_bytes(h[:2], "big") % 100 < percent

